/** Swap URLs here when the final files arrive; null music is intentionally silent. */
interface SoundEntry {
  channel: "effects" | "voice" | "music";
  /** Placeholder beep (Hz) when the file is missing; 0 = silent. */
  frequency: number;
  ms: number;
  url: string | null;
  fallback?: string;
  /** Level for this file, 0–1 (default 1), on top of the caller's volume and the channel slider. */
  volume?: number;
  /** A looping effect (ensureLoop): its MP3 padding is trimmed like the music beds'. */
  loop?: boolean;
  /** Play cap: a play this soon (ms) after the slot's last one is dropped. */
  gapMs?: number;
  /** Play cap: how many of this slot's plays may sound at once. */
  voices?: number;
  /** Playback rate for this slot's file (a shared recording played lower or higher), default 1. */
  rate?: number;
}
